// One clean brief, whether it came from the form or the Writing queue
const s = $('Set blog writer settings').first().json, j = $json;
const topic = String(j.topic || '').trim();
if (!topic) throw new Error('No topic given.');
return [{ json: { topic, primary_keyword: String(j.primary_keyword || topic).trim().toLowerCase(),
  secondary_keywords: j.secondary_keywords || '', audience: j.audience || s.default_audience,
  word_count: Math.min(Math.max(Number(j.word_count) || Number(s.default_word_count) || 1200, 400), 3500),
  brief: j.brief || j.notes || '', source_urls: j.source_urls || '', queue_id: j.queue_id || '', from_queue: !!j.from_queue } }];

// What the research agent reads: Google Autocomplete questions, your source pages
const s = $('Set blog writer settings').first().json, b = $('Prepare the brief').first().json;
const kw = b.primary_keyword, hl = s.wiki_language || 'en';
const sug = q => `https://suggestqueries.google.com/complete/search?client=firefox&hl=${hl}&q=${encodeURIComponent(q)}`;
const out = [kw, `how ${kw}`, `what is ${kw}`, `why ${kw}`, `${kw} vs`, `best ${kw}`].map(q => ({ json: { kind: 'suggest', url: sug(q) } }));
for (const u of String(b.source_urls || '').split(/[\s,]+/).filter(u => /^https?:\/\//.test(u)).slice(0, 4)) out.push({ json: { kind: 'page', url: u } });
return out;

// Turn the fetched sources into compact research notes for the agents
const b = $('Prepare the brief').first().json;
const wiki = $('Search Wikipedia').first().json || {};
const pages = Object.values((wiki.query || {}).pages || {}).sort((a, c) => (a.index || 0) - (c.index || 0));
const strip = h => String(h || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<nav[\s\S]*?<\/nav>|<footer[\s\S]*?<\/footer>|<header[\s\S]*?<\/header>/gi, ' ')
  .replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const reqs = $('Plan research lookups').all().map(i => i.json);
const questions = new Set(), sources = [], news = [], sitemap = [];
$input.all().forEach((item, i) => {
  const req = reqs[i] || {};
  const body = String(item.json.data ?? item.json.body ?? '');
  if (req.kind === 'suggest') { try { (JSON.parse(body)[1] || []).forEach(q => questions.add(String(q))); } catch (e) {} }
  else if (req.kind === 'page') { const t = strip(body); if (t.length > 200) sources.push({ url: req.url, text: t.slice(0, 4000) }); }
  else if (req.kind === 'feed') {
    for (const m of body.matchAll(/<item[\s>]([\s\S]*?)<\/item>|<entry[\s>]([\s\S]*?)<\/entry>/gi)) {
      const x = m[1] || m[2];
      const title = strip((x.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
      const link = (x.match(/<link>([^<]+)<\/link>/i) || x.match(/<link[^>]+href="([^"]+)"/i) || [])[1] || '';
      const desc = strip((x.match(/<description>([\s\S]*?)<\/description>|<summary[^>]*>([\s\S]*?)<\/summary>/i) || []).slice(1).find(Boolean));
      if (title) news.push({ title, link, desc: desc.slice(0, 300) });
    }
  }
  else if (req.kind === 'sitemap') { for (const m of body.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)) sitemap.push(m[1]); }
});
const words = t => String(t).toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3);
const kwWords = words(b.primary_keyword + ' ' + b.topic);
const relNews = news.filter(n => kwWords.some(w => (n.title + ' ' + n.desc).toLowerCase().includes(w))).slice(0, 8);
const topicWords = words(b.primary_keyword + ' ' + b.secondary_keywords + ' ' + b.topic);
const slug = u => { try { return words(decodeURIComponent(new URL(u).pathname)); } catch (e) { return []; } };
const internal_links = sitemap.map(u => ({ u, n: slug(u).filter(w => topicWords.includes(w)).length })).filter(l => l.n > 0)
  .sort((a, c) => c.n - a.n).slice(0, 8).map(l => l.u);
const wikiText = pages.map(p => `${p.title} (${p.fullurl || 'wikipedia'}): ${String(p.extract || '').slice(0, 1500)}`).join('\n\n');
const notes = [wikiText && 'WIKIPEDIA\n' + wikiText, sources.length && 'SOURCE PAGES\n' + sources.map(x => `[${x.url}]\n${x.text}`).join('\n\n'),
  relNews.length && 'RECENT NEWS\n' + relNews.map(n => `- ${n.title} (${n.link}): ${n.desc}`).join('\n')].filter(Boolean).join('\n\n').slice(0, 14000);
return [{ json: { ...b, research_notes: notes || 'No sources could be fetched. Use only well-established general knowledge and avoid specific statistics.',
  questions: [...questions].filter(q => q !== b.primary_keyword).slice(0, 15), internal_links, source_count: pages.length + sources.length + relNews.length,
  sources: [...pages.map(p => p.fullurl).filter(Boolean), ...sources.map(x => x.url), ...relNews.map(n => n.link)].slice(0, 12) } }];

parameters.text:
=You are the RESEARCH agent in a blog-writing team. Read the notes and prepare a fact sheet for the writer.

Topic: {{ $json.topic }}
Primary keyword: {{ $json.primary_keyword }} | secondary keywords: {{ $json.secondary_keywords || '-' }}
Audience: {{ $json.audience }}
Editor's brief: {{ $json.brief || 'none' }}
Questions people search: {{ $json.questions.join(' | ') || 'none found' }}

Research notes:
"""{{ $json.research_notes }}"""

Return:
- angle: the most useful angle for this audience.
- key_facts: 5-12 facts taken ONLY from the notes, each with its source URL ("general knowledge" for widely known basics). Never invent statistics, dates or quotes.
- questions_to_answer: 4-8 questions the article must answer.
- terms: related terms and entities to cover naturally.
- cautions: claims to avoid or hedge (outdated, disputed or needing a source).

parameters.jsonSchemaExample:
{
  "angle": "A realistic first week for complete beginners",
  "key_facts": [
    {
      "fact": "Cooked rice should be cooled and refrigerated within an hour.",
      "source": "https://en.wikipedia.org/wiki/Meal_preparation"
    }
  ],
  "questions_to_answer": [
    "How long does meal prep last?"
  ],
  "terms": [
    "batch cooking",
    "food safety"
  ],
  "cautions": [
    "Do not give exact fridge times without a source"
  ]
}

parameters.text:
=You are the OUTLINE agent. Build the structure for this article.

Topic: {{ $('Collect research notes').first().json.topic }} | primary keyword: {{ $('Collect research notes').first().json.primary_keyword }} | secondary: {{ $('Collect research notes').first().json.secondary_keywords || '-' }}
Audience: {{ $('Collect research notes').first().json.audience }} | target length: about {{ $('Collect research notes').first().json.word_count }} words | language: {{ $('Set blog writer settings').first().json.language }}
Angle: {{ $json.output.angle }}
Questions to answer: {{ ($json.output.questions_to_answer || []).join(' | ') }}
Key facts: {{ JSON.stringify($json.output.key_facts || []) }}
Editor's brief: {{ $('Collect research notes').first().json.brief || 'none' }}

Return title (under 60 characters, includes the primary keyword naturally), slug, meta_description (under 155 characters), intro_hook, sections (4-8 H2s, each with points and a words target; the targets add up to about the total), faq (3-5 questions with a short answer hint) and cta.

parameters.jsonSchemaExample:
{
  "title": "Meal Prep for Beginners: Your First Week",
  "slug": "meal-prep-for-beginners",
  "meta_description": "A simple first week of meal prep for beginners.",
  "intro_hook": "Sunday, two hours, five lunches.",
  "sections": [
    {
      "h2": "What meal prep is (and isn't)",
      "points": [
        "three styles"
      ],
      "words": 200
    }
  ],
  "faq": [
    {
      "q": "How long does meal prep keep?",
      "a_hint": "Use the fridge guidance from the facts"
    }
  ],
  "cta": "Try one recipe this weekend."
}

parameters.text:
=You are the WRITER agent. Write the full article in Markdown.

Outline: {{ JSON.stringify($json.output) }}
Facts you may use (with sources): {{ JSON.stringify($('Research agent').first().json.output.key_facts || []) }}
Cautions: {{ ($('Research agent').first().json.output.cautions || []).join(' | ') || 'none' }}
Primary keyword: {{ $('Collect research notes').first().json.primary_keyword }} | secondary: {{ $('Collect research notes').first().json.secondary_keywords || '-' }}
Audience: {{ $('Collect research notes').first().json.audience }} | brand voice: {{ $('Set blog writer settings').first().json.brand_voice }} | language: {{ $('Set blog writer settings').first().json.language }}
Target length: about {{ $('Collect research notes').first().json.word_count }} words.

Rules:
- Start with "# " + the title, then a 2-3 sentence intro that delivers the hook.
- Use the outline's H2s (##), short paragraphs and lists where they help the reader.
- Put the primary keyword in the first 100 words and in one or two headings, naturally. Use secondary keywords only where they fit.
- Use only the facts above. If you need a number you don't have, write around it. When you use a fact from a URL, link it inline as [text](url).
- End with "## FAQ" (each question as ### with a 2-4 sentence answer), then a short conclusion with the call to action.
- No filler ("In today's fast-paced world", "delve", "game-changer", "unlock"). Output only the article.

