// Latest version of the article; round 1 = first draft, 2+ = revisions
const text = String($json.text || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/^\s*```(?:markdown|md)?\s*/i, '').replace(/```\s*$/, '').trim();
return [{ json: { article: text, round: $runIndex + 1, word_count: text.split(/\s+/).filter(Boolean).length } }];

parameters.text:
=You are the EDITOR and SEO agent. Score this draft strictly and list concrete fixes.

Primary keyword: {{ $('Collect research notes').first().json.primary_keyword }} | secondary: {{ $('Collect research notes').first().json.secondary_keywords || '-' }}
Audience: {{ $('Collect research notes').first().json.audience }} | brand voice: {{ $('Set blog writer settings').first().json.brand_voice }}
Target length: about {{ $('Collect research notes').first().json.word_count }} words | this draft: {{ $json.word_count }} words (round {{ $json.round }})
Facts the writer was given: {{ JSON.stringify($('Research agent').first().json.output.key_facts || []) }}
Questions it must answer: {{ ($('Research agent').first().json.output.questions_to_answer || []).join(' | ') }}

Draft:
"""{{ $json.article }}"""

Score each 0-100: seo (keyword in title, intro and a heading; clear H2/H3 structure; links), readability (short paragraphs, plain words, scannable), accuracy (every specific claim is backed by the facts; anything invented scores low), voice (matches the brand voice, no AI cliches), completeness (answers the questions, within 15% of the target length).
overall: weighted average with accuracy counted twice.
must_fix: up to 8 specific, actionable fixes, quoting the sentence to change. Empty if none.
verdict: "publish" or "revise".

parameters.jsonSchemaExample:
{
  "scores": {
    "seo": 85,
    "readability": 80,
    "accuracy": 70,
    "voice": 85,
    "completeness": 75
  },
  "overall": 78,
  "must_fix": [
    "'Rice keeps for a week' is not in the facts: remove it or hedge it."
  ],
  "verdict": "revise"
}

parameters.jsCode:
// Revise again only if the score is under the bar, the editor listed fixes and rounds are left
const s = $('Set blog writer settings').first().json, d = $('Current draft').last().json, o = $json.output || {};
const sc = o.scores || {};
const vals = ['seo', 'readability', 'accuracy', 'voice', 'completeness'].map(k => Number(sc[k])).filter(n => !isNaN(n));
const overall = Math.round(Number(o.overall) || (vals.length ? vals.reduce((a, c) => a + c, 0) / vals.length : 0));
const fixes = (o.must_fix || []).filter(Boolean);
const needs = overall < (Number(s.min_quality_score) || 80) && fixes.length > 0 && d.round <= (Number(s.max_edit_rounds) || 1);
return [{ json: { ...d, scores: sc, overall, must_fix: fixes, verdict: o.verdict || '', needs_revision: needs } }];

parameters.text:
=You are the WRITER agent revising your draft after the editor's review.

Apply every fix below, keep everything else that works, keep the Markdown structure and about {{ $('Collect research notes').first().json.word_count }} words. Use only these facts: {{ JSON.stringify($('Research agent').first().json.output.key_facts || []) }}
Brand voice: {{ $('Set blog writer settings').first().json.brand_voice }} | language: {{ $('Set blog writer settings').first().json.language }}

Editor's fixes:
{{ $json.must_fix.map((f, i) => (i + 1) + '. ' + f).join('\n') }}

Draft:
"""{{ $json.article }}"""

Output only the full revised article.

