const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Final clean-up: Markdown for Google Docs, simple HTML for WordPress, metadata
const s = $('Set blog writer settings').first().json, b = $('Collect research notes').first().json, ol = $('Outline agent').first().json.output || {}, d = $('Decide next step').last().json;
let md = d.article;
if (!/^#\s/.test(md)) md = `# ${ol.title || b.topic}\n\n` + md;
const title = ((md.match(/^#\s+(.+)$/m) || [])[1] || ol.title || b.topic).trim();
const body = md.replace(/^#\s+.+\n+/, '');
const inline = t => esc(t).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/(^|\W)\*(?!\s)(.+?)\*(?=\W|$)/g, '$1<em>$2</em>')
  .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2">$1</a>');
const html = []; let list = null;
const close = () => { if (list) { html.push(`</${list}>`); list = null; } };
for (const raw of body.split('\n')) {
  const l = raw.trim();
  let m;
  if (!l) { close(); continue; }
  if ((m = l.match(/^(#{2,4})\s+(.+)/))) { close(); html.push(`<h${m[1].length}>${inline(m[2])}</h${m[1].length}>`); }
  else if ((m = l.match(/^[-*]\s+(.+)/))) { if (list !== 'ul') { close(); html.push('<ul>'); list = 'ul'; } html.push(`<li>${inline(m[1])}</li>`); }
  else if ((m = l.match(/^\d+[.)]\s+(.+)/))) { if (list !== 'ol') { close(); html.push('<ol>'); list = 'ol'; } html.push(`<li>${inline(m[1])}</li>`); }
  else if (l.startsWith('>')) { close(); html.push(`<blockquote>${inline(l.replace(/^>\s?/, ''))}</blockquote>`); }
  else { close(); html.push(`<p>${inline(l)}</p>`); }
}
close();
const faq_schema = '';
const words = body.split(/\s+/).filter(Boolean).length;
const sc = d.scores || {};
const header = [`Meta description: ${ol.meta_description || ''}`, `Slug: ${ol.slug || ''}`, `Primary keyword: ${b.primary_keyword}`,
  `Words: ${words} | Quality score: ${d.overall}/100 (SEO ${sc.seo ?? '-'}, readability ${sc.readability ?? '-'}, accuracy ${sc.accuracy ?? '-'}, voice ${sc.voice ?? '-'}, completeness ${sc.completeness ?? '-'}) | Edit rounds: ${d.round}`,
  d.must_fix.length && d.needs_revision === false && d.overall < (Number(s.min_quality_score) || 80) ? `Editor's open points: ${d.must_fix.join(' / ')}` : '',
  `Sources: ${(b.sources || []).join(' , ') || 'none'}`].filter(Boolean).join('\n');
const doc_text = `${title}\n\n${header}\n\n----------\n\n${body}` + (faq_schema ? `\n\n----------\nFAQ schema (paste into a Custom HTML block):\n<script type="application/ld+json">${faq_schema}</script>` : '');
return [{ json: { title, slug: ol.slug || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''), meta_description: ol.meta_description || '',
  markdown: md, html: html.join('\n') + (faq_schema ? `\n<script type="application/ld+json">${faq_schema}</script>` : ''), faq_schema,
  words, overall: d.overall, scores: sc, rounds: d.round, open_points: d.must_fix.join(' / '), doc_text } }];
